21	/** Render bot/agent text with clickable links — markdown [label](url) and bare
22	 *  URLs (absolute or site-relative). Internal links open in place; external in a
23	 *  new tab. Everything else is plain text (the container keeps line breaks). */
24	function renderRich(text: string): ReactNode[] {
25	  const out: ReactNode[] = [];
26	  const re = /\[([^\]]+)\]\((https?:\/\/[^\s)]+|\/[^\s)]+)\)|(https?:\/\/[^\s]+|\/[a-z0-9][^\s]*)/gi;
27	  let last = 0;
28	  let key = 0;
29	  let m: RegExpExecArray | null;
30	  while ((m = re.exec(text)) !== null) {
31	    if (m.index > last) out.push(text.slice(last, m.index));
32	    const label = m[1] ?? m[3];
33	    const href = m[2] ?? m[3];
34	    const external = /^https?:\/\//i.test(href);
35	    out.push(
36	      <a
37	        key={`l${key++}`}
38	        href={href}
39	        {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
40	        className="font-medium text-brand-300 underline underline-offset-2 hover:text-brand-200"
41	      >
42	        {label}
43	      </a>,
44	    );
45	    last = re.lastIndex;
46	  }
47	  if (last < text.length) out.push(text.slice(last));
48	  return out;
49	}
