124	const VISITOR_KEY = "nxeon_chat_visitor";
125	// The active conversation lives in sessionStorage so a NEW browser session
126	// (coming back later) starts a fresh chat, while past threads stay resumable
127	// from the history list.
128	const ACTIVE_KEY = "nxeon_chat_active";
129	const POLL_MS = 4000;
130	
131	type ConvoSummary = {
132	  id: string;
133	  title: string;
134	  preview: string;
135	  unread: boolean;
136	  status: string;
137	  lastMessageAt: string;
138	};
139	
140	// Client-side pre-checks for fast feedback. The server re-validates every one of
141	// these by file signature — never trust these alone (see lib/chat-attachment.ts).
142	const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
143	const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
144	const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
145	
146	/** Reject before upload for instant UX; the server is the real gate. */
147	function imageError(file: File): string | null {
148	  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
149	  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
150	  return null;
151	}
