153	function getVisitorId(): string {
154	  try {
155	    let id = localStorage.getItem(VISITOR_KEY);
156	    if (!id) {
157	      id =
158	        typeof crypto !== "undefined" && crypto.randomUUID
159	          ? crypto.randomUUID()
160	          : `v_${Date.now()}_${Math.random().toString(36).slice(2)}`;
161	      localStorage.setItem(VISITOR_KEY, id);
162	    }
163	    return id;
164	  } catch {
165	    return `v_${Date.now()}_${Math.random().toString(36).slice(2)}`;
166	  }
167	}
