169	/** Three-dot "typing…" pulse. Uses Tailwind's built-in `animate-pulse` with
170	 *  staggered delays so it reads as a wave without any new global keyframes. */
171	function TypingDots() {
172	  return (
173	    <span className="flex items-center gap-1">
174	      {[0, 150, 300].map((delay) => (
175	        <span
176	          key={delay}
177	          className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-300"
178	          style={{ animationDelay: `${delay}ms`, animationDuration: "1s" }}
179	        />
180	      ))}
181	    </span>
182	  );
183	}
