185	export default function ChatWidget({ viewer = null }: { viewer?: ChatViewer }) {
186	  // The customer-facing live-chat bubble is mounted globally by the root layout,
187	  // so it also lands on the admin ops portal — where it makes no sense (staff
188	  // answer chats from /admin/chat, they don't open a visitor chat with
189	  // themselves). Suppress it on every /admin route; the admin portal shows its
190	  // own support + email indicator widgets instead (components/admin/AdminIndicators).
191	  const pathname = usePathname();
192	  const onAdmin = pathname?.startsWith("/admin") ?? false;
193	  const isAuthed = !!viewer;
194	  const [open, setOpen] = useState(false);
195	  const consentPending = useConsentPending();
196	  const [visitorId, setVisitorId] = useState("");
197	  const [messages, setMessages] = useState<Msg[]>([]);
198	  const [draft, setDraft] = useState("");
199	  const [name, setName] = useState(viewer?.name ?? "");
200	  const [email, setEmail] = useState(viewer?.email ?? "");
201	  const [sending, setSending] = useState(false);
202	  const [error, setError] = useState("");
203	  const [started, setStarted] = useState(false);
204	  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
205	  const [agentTyping, setAgentTyping] = useState(false);
206	  const [botThinking, setBotThinking] = useState(false); // "processing…" before a bot reply reveals
207	  const [activeId, setActiveId] = useState<string | null>(null); // conversation being viewed
208	  const [convos, setConvos] = useState<ConvoSummary[]>([]); // past conversations for the history list
209	  const [showHistory, setShowHistory] = useState(false);
210	  const scrollRef = useRef<HTMLDivElement>(null);
211	  const fileInputRef = useRef<HTMLInputElement>(null);
212	  const lastTypingPingRef = useRef(0); // throttle "I am typing" pings
213	  const botThinkingRef = useRef(false); // read inside poll without re-creating it
214	  const atBottomRef = useRef(true); // is the user pinned to the newest message?
215	
216	  useEffect(() => setVisitorId(getVisitorId()), []);
217	  useEffect(() => {
218	    botThinkingRef.current = botThinking;
219	  }, [botThinking]);
220	
221	  /** Missing-identity check for anonymous visitors before the first message. */
222	  function identityError(): string | null {
223	    if (isAuthed || started) return null;
224	    if (!name.trim() || !EMAIL_RE.test(email.trim())) {
225	      return "Please add your name and a valid email to start the chat.";
226	    }
227	    return null;
228	  }
229	
230	  /** Reveal server messages, but if the bot just replied, show a short
231	   *  "processing…" animation first so the answer doesn't pop instantly. */
232	  function revealMessages(next: Msg[], shownBotIds: Set<string>) {
233	    const newBot = next.find((m) => m.sender === "bot" && !shownBotIds.has(m.id));
234	    if (!newBot) {
235	      setMessages(next);
236	      return;
237	    }
238	    setBotThinking(true);
239	    const delay = Math.min(2400, 650 + (newBot.body?.length ?? 0) * 9);
240	    window.setTimeout(() => {
241	      setMessages(next);
242	      setBotThinking(false);
243	    }, delay);
244	  }
245	
246	  // Revoke the object URL for the preview thumbnail when it changes / unmounts.
247	  useEffect(() => {
248	    return () => {
249	      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
250	    };
251	  }, [pendingImage]);
252	
253	  const attachUrl = useCallback(
254	    (a: Attachment) =>
255	      `/api/chat/attachment/${a.id}?visitorId=${encodeURIComponent(visitorId)}`,
256	    [visitorId]
257	  );
258	
259	  function pickImage(file: File | null | undefined) {
260	    if (!file) return;
261	    const err = imageError(file);
262	    if (err) {
263	      setError(err);
264	      return;
265	    }
266	    setError("");
267	    setPendingImage((prev) => {
268	      if (prev) URL.revokeObjectURL(prev.url);
269	      return { file, url: URL.createObjectURL(file) };
270	    });
271	  }
272	
273	  function clearImage() {
274	    setPendingImage((prev) => {
275	      if (prev) URL.revokeObjectURL(prev.url);
276	      return null;
277	    });
278	    if (fileInputRef.current) fileInputRef.current.value = "";
279	  }
280	
281	  function onPaste(e: ClipboardEvent) {
282	    const item = Array.from(e.clipboardData?.items ?? []).find((i) =>
283	      i.type.startsWith("image/")
284	    );
285	    if (item) {
286	      const file = item.getAsFile();
287	      if (file) {
288	        e.preventDefault();
289	        pickImage(file);
290	      }
291	    }
292	  }
293	
294	  async function sendImage(body: string, shownBotIds: Set<string>) {
295	    if (!pendingImage) return;
296	    const fd = new FormData();
297	    fd.append("visitorId", visitorId);
298	    if (activeId) fd.append("conversationId", activeId);
299	    fd.append("file", pendingImage.file);
300	    if (body) fd.append("body", body);
301	    if (name.trim()) fd.append("name", name.trim());
302	    if (email.trim()) fd.append("email", email.trim());
303	    const res = await fetch("/api/chat/upload", { method: "POST", body: fd });
304	    if (!res.ok) {
305	      const j = (await res.json().catch(() => ({}))) as { error?: string };
306	      setError(j.error ?? "Could not send image. Please try again.");
307	      return;
308	    }
309	    const data = (await res.json()) as { conversation?: { id: string } | null; messages: Msg[] };
310	    setStarted(true);
311	    adopt(data.conversation?.id);
312	    revealMessages(data.messages ?? [], shownBotIds);
313	    loadConvos();
314	    clearImage();
315	  }
316	
317	  const poll = useCallback(async () => {
318	    if (!visitorId || !activeId) return; // a brand-new (unstarted) chat has nothing to poll
319	    if (botThinkingRef.current) return; // don't let a poll reveal the bot mid-animation
320	    try {
321	      const res = await fetch(
322	        `/api/chat?visitorId=${encodeURIComponent(visitorId)}&conversationId=${encodeURIComponent(activeId)}`,
323	        { cache: "no-store" },
324	      );
325	      if (!res.ok) return;
326	      const data = (await res.json()) as {
327	        conversation: unknown;
328	        messages: Msg[];
329	        typing?: { agent?: boolean };
330	      };
331	      if (data.conversation) {
332	        setStarted(true);
333	        setMessages(data.messages ?? []);
334	      }
335	      // Agent-typing self-expires server-side, so a stale poll can only clear it.
336	      setAgentTyping(Boolean(data.typing?.agent));
337	    } catch {
338	      /* transient network error — next poll retries */
339	    }
340	  }, [visitorId, activeId]);
341	
342	  // Adopt a conversation id returned by the server (or chosen from history) and
343	  // remember it for this browser session.
344	  const adopt = useCallback((id: string | null | undefined) => {
345	    if (!id) return;
346	    setActiveId(id);
347	    try {
348	      sessionStorage.setItem(ACTIVE_KEY, id);
349	    } catch {
350	      /* private mode — active id just won't persist across reloads */
351	    }
352	  }, []);
353	
354	  const loadConvos = useCallback(async () => {
355	    if (!visitorId) return;
356	    try {
357	      const res = await fetch(`/api/chat/list?visitorId=${encodeURIComponent(visitorId)}`, {
358	        cache: "no-store",
359	      });
360	      if (!res.ok) return;
361	      const data = (await res.json()) as { conversations: ConvoSummary[] };
362	      setConvos(data.conversations ?? []);
363	    } catch {
364	      /* history list is non-essential */
365	    }
366	  }, [visitorId]);
367	
368	  function startNewChat() {
369	    setActiveId(null);
370	    try {
371	      sessionStorage.removeItem(ACTIVE_KEY);
372	    } catch {
373	      /* ignore */
374	    }
375	    setMessages([]);
376	    setStarted(false);
377	    setDraft("");
378	    setError("");
379	    clearImage();
380	    setShowHistory(false);
381	  }
382	
383	  const openConvo = useCallback(
384	    async (id: string) => {
385	      adopt(id);
386	      setShowHistory(false);
387	      setStarted(true);
388	      try {
389	        const res = await fetch(
390	          `/api/chat?visitorId=${encodeURIComponent(visitorId)}&conversationId=${encodeURIComponent(id)}`,
391	          { cache: "no-store" },
392	        );
393	        if (res.ok) {
394	          const data = (await res.json()) as { messages: Msg[] };
395	          setMessages(data.messages ?? []);
396	        }
397	      } catch {
398	        /* next poll will fill it */
399	      }
400	    },
401	    [visitorId, adopt],
402	  );
403	
404	  // Tell the server the visitor is typing, throttled to ~once per 2.5s. Only
405	  // meaningful once a conversation exists (nothing to attach the signal to yet).
406	  const pingTyping = useCallback(() => {
407	    if (!visitorId || !started) return;
408	    const now = Date.now();
409	    if (now - lastTypingPingRef.current < 2500) return;
410	    lastTypingPingRef.current = now;
411	    fetch("/api/chat/typing", {
412	      method: "POST",
413	      headers: { "Content-Type": "application/json" },
414	      body: JSON.stringify({ visitorId }),
415	      keepalive: true,
416	    }).catch(() => {
417	      /* best-effort — the indicator simply won't show */
418	    });
419	  }, [visitorId, started]);
420	
421	  // Poll while the panel is open.
422	  useEffect(() => {
423	    if (!open || !visitorId) return;
424	    poll();
425	    const t = setInterval(poll, POLL_MS);
426	    return () => clearInterval(t);
427	  }, [open, visitorId, poll]);
428	
429	  // On open: load the history list and resume this session's active chat (if
430	  // any). A new browser session has no saved active id → a fresh chat.
431	  useEffect(() => {
432	    if (!open || !visitorId) return;
433	    loadConvos();
434	    let saved: string | null = null;
435	    try {
436	      saved = sessionStorage.getItem(ACTIVE_KEY);
437	    } catch {
438	      /* ignore */
439	    }
440	    if (saved && !activeId) openConvo(saved);
441	    // eslint-disable-next-line react-hooks/exhaustive-deps
442	  }, [open, visitorId]);
443	
444	  // Track whether the user is pinned to the bottom. Updated on every scroll so
445	  // the auto-scroll effect below can tell "reading history" from "at the latest".
446	  function handleScroll() {
447	    const el = scrollRef.current;
448	    if (!el) return;
449	    atBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 120;
450	  }
451	
452	  // Follow new messages ONLY when the user is already at the bottom. Polling
453	  // replaces the messages array on every tick, so unconditionally scrolling here
454	  // used to yank the reader back down whenever they scrolled up to read history.
455	  useEffect(() => {
456	    if (atBottomRef.current) {
457	      scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
458	    }
459	  }, [messages]);
460	
461	  // Opening the widget always jumps to the newest message.
462	  useEffect(() => {
463	    if (open) {
464	      atBottomRef.current = true;
465	      const el = scrollRef.current;
466	      if (el) el.scrollTo({ top: el.scrollHeight });
467	    }
468	  }, [open]);
469	
470	  async function send() {
471	    const body = draft.trim();
472	    if (sending || !visitorId) return;
473	    if (!body && !pendingImage) return;
474	
475	    // Anonymous visitors must give name + email before the first message.
476	    const idErr = identityError();
477	    if (idErr) {
478	      setError(idErr);
479	      return;
480	    }
481	
482	    setSending(true);
483	    setError("");
484	    atBottomRef.current = true; // sending means "follow the reply" — pin to bottom
485	
486	    // Bot messages already on screen — so we can tell when a NEW one arrives and
487	    // play the "processing…" animation before revealing it.
488	    const shownBotIds = new Set(messages.filter((m) => m.sender === "bot").map((m) => m.id));
489	
490	    // Image (optionally with a caption) goes through the multipart upload path.
491	    if (pendingImage) {
492	      setDraft("");
493	      try {
494	        await sendImage(body, shownBotIds);
495	      } catch {
496	        setError("Network error. Please try again.");
497	      } finally {
498	        setSending(false);
499	      }
500	      return;
501	    }
502	
503	    // Optimistic echo so the input feels instant.
504	    const optimistic: Msg = {
505	      id: `tmp_${Date.now()}`,
506	      sender: "visitor",
507	      body,
508	      createdAt: new Date().toISOString(),
509	    };
510	    setMessages((m) => [...m, optimistic]);
511	    setDraft("");
512	    try {
513	      const res = await fetch("/api/chat", {
514	        method: "POST",
515	        headers: { "Content-Type": "application/json" },
516	        body: JSON.stringify({
517	          visitorId,
518	          conversationId: activeId ?? undefined,
519	          body,
520	          name: name.trim() || undefined,
521	          email: email.trim() || undefined,
522	        }),
523	      });
524	      if (!res.ok) {
525	        const j = (await res.json().catch(() => ({}))) as { error?: string };
526	        setError(j.error ?? "Could not send. Please try again.");
527	        return;
528	      }
529	      const data = (await res.json()) as { conversation?: { id: string }; messages: Msg[] };
530	      setStarted(true);
531	      adopt(data.conversation?.id);
532	      revealMessages(data.messages ?? [], shownBotIds);
533	      loadConvos();
534	    } catch {
535	      setError("Network error. Please try again.");
536	    } finally {
537	      setSending(false);
538	    }
539	  }
540	
541	  // Placed after every hook so the hook order is stable — the admin portal simply
542	  // renders nothing for this widget.
543	  if (onAdmin) return null;
544	
545	  return (
546	    <div
547	      /*
548	        While the cookie banner is waiting for an answer it owns the bottom of the
549	        viewport (z-[70]). At 375px the bubble used to paint straight over its
550	        "Accept all" row. Lift out of the banner's way on small screens until the
551	        visitor has chosen — only while the panel is CLOSED, because a 30rem panel
552	        pushed up by the banner's height would run off the top of a short phone.
553	      */
554	      className={`fixed bottom-4 right-4 z-[60] flex flex-col items-end gap-3 ${
555	        consentPending && !open ? "max-sm:mb-52" : ""
556	      }`}
557	    >
558	      {open && (
559	        <div className="card glass relative flex h-[30rem] w-[22rem] max-w-[calc(100vw-2rem)] flex-col overflow-hidden p-0 shadow-2xl">
560	          {/* Previous-conversations overlay */}
561	          {showHistory && (
562	            <div className="absolute inset-0 z-10 flex flex-col bg-[#0b1120]/97 backdrop-blur">
563	              <div className="flex items-center gap-2 border-b border-white/10 px-3 py-3">
564	                <button
565	                  aria-label="Back"
566	                  onClick={() => setShowHistory(false)}
567	                  className="rounded-lg p-1 text-slate-400 hover:bg-white/10 hover:text-slate-200"
