2	import { db } from "@/lib/db";
3	import { greetingIntent, greetingReply } from "@/lib/kb-smalltalk";
4	import { llmAnswer, type LlmImage } from "@/lib/kb-llm";
5	import type { ClaudeMessage } from "@/lib/anthropic";
6	
7	export type KbAnswerOpts = {
8	  history?: ClaudeMessage[];
9	  images?: LlmImage[];
10	  visitorName?: string | null;
11	  /** The signed-in customer's id, when the conversation belongs to one — unlocks
12	   *  the account-aware tool loop (read-only lookups of THEIR account). */
13	  userId?: string | null;
14	  /** When true, skip the paid Claude call and use only token-free retrieval
15	   *  (used by the daily cost-cap guardrail). */
16	  noLlm?: boolean;
17	};
18	
19	/**
20	 * Front door to the Nxeon live-chat AGENT.
21	 *
22	 * The assistant is a Claude-powered agent (lib/kb-llm.ts) that reasons over the
23	 * full operator knowledge base and a suite of live tools — account lookups for
24	 * signed-in customers, plus public tools for plans, platform status, and help
25	 * search — and answers in its own words. There is NO keyword-retrieval fallback
26	 * that pastes blog snippets: retrieval only ever SEEDS the agent as context.
27	 *
28	 * When the model is genuinely unavailable (no key configured, or an API error)
29	 * the bot degrades GRACEFULLY to one warm, honest message that offers a human
30	 * follow-up — it never dumps an article link as "the answer". The failure reason
31	 * rides back on the result so the orchestrator (lib/kb-run.ts) can log a real
32	 * degradation for the operator instead of failing silently.
33	 *
34	 * Every call returns a typed `kind` so app/api/chat/route.ts can log it.
35	 * The index (KbChunk) is (re)built by lib/actions-kb.ts → reindexKb().
36	 */
37	
38	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
39	
40	export type ReplyKind = "smalltalk" | "handoff" | "offer" | "answer" | "degraded";
41	export type KbResult = {
42	  kind: ReplyKind;
43	  reply: string | null;
44	  matchedTitle?: string;
45	  /** Plan-card keys to render with this reply (resolved to cards in kb-run). */
46	  cardKeys?: string[];
47	  /** Present only when the model was unavailable, so the orchestrator can log a
48	   *  real degradation and alert the operator on a hard error (never silent). */
49	  llmFailure?: "no_key" | "error" | "over_cap";
50	};
51	
52	/** Warm, honest degradation — used ONLY when the model can't run (no key / API
53	 *  error / over the daily cap). Never a blog link; offers a human follow-up.
54	 *  Exported so the graceful-degradation contract (offers contact/pricing, never
55	 *  a blog link) can be asserted in a hermetic unit test. */
56	export function degradedReply(reason: "no_key" | "error" | "over_cap", name?: string | null): string {
57	  const who = name && name.trim() ? ` ${name.trim()}` : "";
58	  if (reason === "over_cap") {
59	    return `Thanks${who} — we're helping a lot of people in chat right now, so rather than rush you I want to make sure you get a solid answer. Drop your email with your question and the team will get right back to you (usually within a business day). In the meantime, ${APP_URL}/pricing has every plan and ${APP_URL}/help has quick guides.`;
60	  }
61	  return `Sorry${who} — I'm having a brief problem reaching my assistant just now. I don't want to guess at your answer. If you leave your email and what you need, the team will follow up quickly — or you can reach us any time at ${APP_URL}/contact. You can also check live status at ${APP_URL}/status.`;
62	}
63	
64	/** "which plan / what plan / recommend a plan / best plan / plan for X". */
65	export function planIntent(text: string): boolean {
66	  return /\b(which|what|best)\s+plan\b|\bplan\s+(should|would|do|for|to)\b|\brecommend\s+(a\s+)?plan\b|\bhelp me (choose|pick)\b|\bwhich (one|option|tier)\b/i.test(
67	    text,
68	  );
69	}
70	
71	type Row = { source: string; title: string; url: string | null; snippet: string; offer: boolean; rank: number };
72	
73	/** Explicit "get me a person". */
74	export function humanIntent(text: string): boolean {
75	  return /\b(human(?:\s+(?:being|agent))?|agent|operator|representative|rep|customer\s+(?:service|support|rep)|real\s+(?:person|human)|actual\s+(?:person|human)|live\s+(?:chat|agent|support|person)|someone|a person|talk to (?:a|your|the|someone)|speak (?:to|with)|connect me|get me (?:a|someone))\b/i.test(text);
76	}
77	
78	/** "Do you have any deals / discounts / promos?" */
79	export function offerIntent(text: string): boolean {
80	  return /\b(deal|deals|discount|discounts|promo|promotion|coupon|voucher|offer|offers|sale|cheaper|save (money|some)|free month|free trial|any specials?)\b/i.test(text);
81	}
82	
83	/** Top knowledge-base matches. websearch_to_tsquery parses arbitrary user input
84	 *  safely, so this is injection- and crash-safe for anything a visitor types. */
85	export async function kbSearch(query: string, limit = 4): Promise<Row[]> {
86	  const q = query.trim();
87	  if (q.length < 3) return [];
88	  try {
89	    return await db.$queryRaw<Row[]>`
90	      SELECT source, title, url, snippet, "offer",
91	             ts_rank(to_tsvector('english', title || ' ' || content),
92	                     websearch_to_tsquery('english', ${q})) AS rank
93	      FROM "KbChunk"
94	      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${q})
95	      ORDER BY rank DESC
96	      LIMIT ${limit}`;
97	  } catch {
98	    return [];
99	  }
100	}
101	
102	/**
103	 * Decide how the assistant should respond to a visitor message. Priority:
104	 * explicit human hand-off → the Claude agent (tools + full KB, for everyone) →
105	 * graceful degradation if the model can't run. There is no keyword-retrieval
106	 * fallback and no canned "clarifier" — the agent handles greetings, questions,
107	 * and everything in between. Always returns a `kind` so the caller can log
108	 * coverage. `history` is the prior conversation (oldest→newest) for context.
109	 */
110	export async function kbAnswer(message: string, opts: KbAnswerOpts = {}): Promise<KbResult> {
111	  const history = opts.history ?? [];
112	
113	  // 1. Explicit "get me a person" — hand-off (kb-run turns this into the live
114	  //    escalation + email flow). No tokens spent.
115	  if (humanIntent(message)) {
116	    return {
117	      kind: "handoff",
118	      reply:
119	        "No problem — I'll connect you with our team. Someone will be with you shortly. Feel free to add any details in the meantime.",
120	    };
121	  }
122	
123	  // 2. Over the daily cost cap → degrade gracefully (no model call, no snippet).
124	  if (opts.noLlm) {
125	    return {
126	      kind: "degraded",
127	      reply: degradedReply("over_cap", opts.visitorName),
128	      llmFailure: "over_cap",
129	    };
130	  }
131	
132	  // 3. Seed a little help context (cheap FTS), then run the agent for EVERYONE.
133	  //    The agent investigates with its tools and answers in its own words; plan
134	  //    cards ride back via a hidden [[cards: …]] directive parsed in kb-run.
135	  const rows = await kbSearch(message);
136	  const chunks = rows.map((r) => ({ title: r.title, snippet: r.snippet, url: r.url }));
137	  const res = await llmAnswer({
138	    message,
139	    history,
140	    chunks,
141	    images: opts.images,
142	    visitorName: opts.visitorName ?? null,
143	    userId: opts.userId ?? null,
144	  });
145	
146	  if (res.ok) {
147	    return {
148	      kind: offerIntent(message) ? "offer" : "answer",
149	      reply: res.text,
150	      matchedTitle: rows[0]?.title,
151	    };
152	  }
153	
154	  // 4. Model unavailable. NEVER paste a blog snippet. A plain greeting still gets
155	  //    a warm hello; anything else gets an honest "let me get the team" message.
156	  //    The failure reason rides back so kb-run logs a real degradation.
157	  if (res.reason === "no_key" && greetingIntent(message)) {
158	    return { kind: "smalltalk", reply: greetingReply(opts.visitorName) };
159	  }
160	  return {
161	    kind: "degraded",
162	    reply: degradedReply(res.reason === "error" ? "error" : "no_key", opts.visitorName),
163	    llmFailure: res.reason === "error" ? "error" : "no_key",
164	  };
165	}
