73	export async function POST(req: Request) {
74	  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
75	  if (!rl.ok) {
76	    return NextResponse.json(
77	      { error: "Too many messages. Please slow down." },
78	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
79	    );
80	  }
81	
82	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
83	  const visitorId = clip(raw.visitorId, 100);
84	  const conversationId = clip(raw.conversationId, 40);
85	  const body = clip(raw.body, 5000);
86	  const name = clip(raw.name, 120);
87	  const email = clip(raw.email, 200);
88	
89	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
90	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
91	
92	  const user = await currentUser();
93	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
94	    user?.id ? [{ userId: user.id }] : [],
95	  );
96	
97	  // If the client names a conversation it owns, continue it (resuming past
98	  // history, reopening if it was closed). Otherwise start a brand-new one — we
99	  // no longer auto-resume the latest, so returning gives a fresh chat while old
100	  // threads stay available in the history list.
101	  let convo = conversationId
102	    ? await db.chatConversation.findFirst({
103	        where: { id: conversationId, OR: ownedBy },
104	        select: { id: true, name: true, email: true },
105	      })
106	    : null;
107	
108	  if (!convo) {
109	    // Anonymous (not signed in) visitors must give a name + valid email before
110	    // starting. Signed-in customers already have both, so they're never asked.
111	    if (!user) {
112	      const nm = name ?? null;
113	      const em = email ?? null;
114	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
115	        return NextResponse.json(
116	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
117	          { status: 400 },
118	        );
119	      }
120	    }
121	    convo = await db.chatConversation.create({
122	      data: {
123	        visitorId,
124	        userId: user?.id ?? null,
125	        name: name ?? user?.name ?? null,
126	        email: email ?? user?.email ?? null,
127	      },
128	      select: { id: true, name: true, email: true },
129	    });
130	  }
131	
132	  await db.$transaction([
133	    db.chatMessage.create({
134	      data: { conversationId: convo.id, sender: "visitor", body },
135	    }),
136	    db.chatConversation.update({
137	      where: { id: convo.id },
138	      data: {
139	        status: "OPEN", // reopen if the visitor is resuming a closed thread
140	        unreadForAgent: true,
141	        lastMessageAt: new Date(),
142	        // Backfill identity / link account if it arrives after creation.
143	        ...(user?.id ? { userId: user.id } : {}),
144	        ...(name && !convo.name ? { name } : {}),
145	        ...(email && !convo.email ? { email } : {}),
146	      },
147	    }),
148	  ]);
149	
150	  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
151	  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
152	  // human has engaged.
153	  try {
154	    const { runAssistant } = await import("@/lib/kb-run");
155	    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
156	  } catch {
157	    /* assistant is non-essential — never fail the visitor's message on it */
158	  }
159	
160	  const full = await db.chatConversation.findUnique({
161	    where: { id: convo.id },
162	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
163	  });
164	  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
165	}
