167	export async function GET(req: Request) {
168	  const url = new URL(req.url);
169	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
170	  const conversationId = clip(url.searchParams.get("conversationId"), 40);
171	  if (!visitorId) {
172	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
173	  }
174	
175	  const user = await currentUser();
176	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
177	    user?.id ? [{ userId: user.id }] : [],
178	  );
179	
180	  // Poll a specific conversation when named (scoped to the visitor/user), else
181	  // the most recent open thread for back-compat.
182	  let convo = conversationId
183	    ? await db.chatConversation.findFirst({
184	        where: { id: conversationId, OR: ownedBy },
185	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
186	      })
187	    : await db.chatConversation.findFirst({
188	        where: { visitorId, status: "OPEN" },
189	        orderBy: { lastMessageAt: "desc" },
190	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
191	      });
192	
193	  if (!convo) {
194	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
195	  }
196	
197	  // If the bot is waiting on a live agent, let the poll drive the handoff window:
198	  // post the "no agents available" fallback once it elapses, then refresh so the
199	  // visitor sees it on this same poll rather than the next one.
200	  if (convo.botEscalatedAt) {
201	    try {
202	      const { checkEscalationTimeout } = await import("@/lib/kb-run");
203	      await checkEscalationTimeout(convo.id);
204	      const refreshed = await db.chatConversation.findFirst({
205	        where: { id: convo.id },
206	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
207	      });
208	      if (refreshed) convo = refreshed;
209	    } catch {
210	      /* non-essential */
211	    }
212	  }
213	
214	  // Reading the thread clears the visitor-facing unread flag.
215	  if (convo.unreadForUser) {
216	    await db.chatConversation
217	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
218	      .catch(() => {});
219	  }
220	
221	  // The whole support transcript, plus the name/email the visitor gave. The
222	  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
223	  // itself the secret — precisely the shape a shared cache must never store.
224	  //
225	  // `typing.agent` tells the widget whether a support agent is composing a reply
226	  // right now; it self-expires, so a stale poll can only ever under-report.
227	  return NextResponse.json(
228	    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent } },
229	    { headers: NO_STORE_HEADERS },
230	  );
231	}
